import React, { useState } from "react";
import { useLanguage } from "./Languagecontext";
import { Routes, Route, useNavigate } from "react-router-dom";
import "./App.css";

// Welcome Screen
function WelcomeScreen() {
  const { language, changeLanguage, t } = useLanguage();
  const navigate = useNavigate();

  const [selectedLanguage, setSelectedLanguage] = useState(
    language || ""
  );

  const [started, setStarted] = useState(Boolean(language));

  const handleContinue = () => {
    if (!selectedLanguage) {
      alert("Please select a language / దయచేసి భాషను ఎంచుకోండి");
      return;
    }

    changeLanguage(selectedLanguage);
    setStarted(true);
  };

  const handleLanguageChange = (newLanguage) => {
    setSelectedLanguage(newLanguage);
    changeLanguage(newLanguage);
  };

  return (
    <div className="app-container">
      {!started ? (
        <div className="language-card">
          <div className="app-logo">🌾</div>

          <h1>Harvest Hub</h1>

          <p className="tagline">
            Connecting Farmers and Workers
          </p>

          <h2>Choose Your Language</h2>
          <h3>మీ భాషను ఎంచుకోండి</h3>

          <div className="language-options">
            <button
              className={
                selectedLanguage === "en"
                  ? "language-btn selected"
                  : "language-btn"
              }
              onClick={() => setSelectedLanguage("en")}
            >
              🇬🇧 English
            </button>

            <button
              className={
                selectedLanguage === "te"
                  ? "language-btn selected"
                  : "language-btn"
              }
              onClick={() => setSelectedLanguage("te")}
            >
              🇮🇳 తెలుగు
            </button>
          </div>

          <button
            className="continue-btn"
            onClick={handleContinue}
          >
            Continue / కొనసాగించండి →
          </button>
        </div>
      ) : (
        <div className="welcome-card">
          <div className="top-bar">
            <h2>{t.appName}</h2>

            <select
              value={language}
              onChange={(e) =>
                handleLanguageChange(e.target.value)
              }
              aria-label="Change language"
            >
              <option value="en">English</option>
              <option value="te">తెలుగు</option>
            </select>
          </div>

          <div className="welcome-content">
            <div className="app-logo">🌾</div>

            <h1>{t.welcome}</h1>

            <p>{t.description}</p>

            <h3>{t.selectRole}</h3>

            <div className="role-options">
              <button
                className="role-btn"
                onClick={() => navigate("/farmer-login")}
              >
                👨‍🌾 {t.farmer}
              </button>

              <button
                className="role-btn"
                onClick={() => navigate("/worker-login")}
              >
                👷 {t.worker}
              </button>
            </div>

            <p className="coming-soon">
              {t.dashboard} — Coming Soon
            </p>
          </div>
        </div>
      )}
    </div>
  );
}

// Farmer Login Page
function FarmerLogin() {
  const { language } = useLanguage();
  const navigate = useNavigate();

  return (
    <div className="app-container">
      <div className="welcome-card">
        <div className="app-logo">👨‍🌾</div>

        <h1>
          {language === "te"
            ? "రైతు లాగిన్"
            : "Farmer Login"}
        </h1>

        <p>
          {language === "te"
            ? "హార్వెస్ట్ హబ్‌కు స్వాగతం"
            : "Welcome to Harvest Hub"}
        </p>

        <button
          className="continue-btn"
          onClick={() => navigate("/")}
        >
          ← {language === "te" ? "హోమ్‌కు తిరిగి వెళ్ళండి" : "Back to Home"}
        </button>
      </div>
    </div>
  );
}

// Worker Login Page
function WorkerLogin() {
  const { language } = useLanguage();
  const navigate = useNavigate();

  return (
    <div className="app-container">
      <div className="welcome-card">
        <div className="app-logo">👷</div>

        <h1>
          {language === "te"
            ? "కూలీ లాగిన్"
            : "Worker Login"}
        </h1>

        <p>
          {language === "te"
            ? "హార్వెస్ట్ హబ్‌కు స్వాగతం"
            : "Welcome to Harvest Hub"}
        </p>

        <button
          className="continue-btn"
          onClick={() => navigate("/")}
        >
          ← {language === "te" ? "హోమ్‌కు తిరిగి వెళ్ళండి" : "Back to Home"}
        </button>
      </div>
    </div>
  );
}

// Main Application Routes
function App() {
  return (
    <Routes>
      <Route path="/" element={<WelcomeScreen />} />
      <Route path="/farmer-login" element={<FarmerLogin />} />
      <Route path="/worker-login" element={<WorkerLogin />} />
    </Routes>
  );
}

export default App;
